import hashlib
import hmac
import os
import struct
import time
import sqlite3
from contextlib import contextmanager

SECRET_KEY = os.environ.get('APP_SECRET', os.urandom(32))
DB_PATH = os.environ.get('DB_PATH', ':memory:')

# Permission levels encoded as 32-bit values
PERM_READ = 0x00000001
PERM_WRITE = 0x00000002
PERM_DELETE = 0x00000004
PERM_ADMIN = 0x80000000  # High bit set = admin
PERM_SUPERADMIN = 0xFFFFFFFF  # All bits set

_ROLE_PERMISSIONS = {
    'viewer': PERM_READ,
    'editor': PERM_READ | PERM_WRITE,
    'moderator': PERM_READ | PERM_WRITE | PERM_DELETE,
    'admin': PERM_ADMIN | PERM_READ | PERM_WRITE | PERM_DELETE,
}


class PermissionEngine:
    """Handles permission checks using bitfield operations.
    Permissions are stored as 32-bit unsigned integers."""

    @staticmethod
    def encode_permissions(role: str, extra_grants: list = None) -> int:
        """Encode role + extra grants into a permission integer."""
        base = _ROLE_PERMISSIONS.get(role, 0)
        if extra_grants:
            for grant in extra_grants:
                if grant in _ROLE_PERMISSIONS:
                    base |= _ROLE_PERMISSIONS[grant]
        return base

    @staticmethod
    def check_permission(user_perms: int, required_perms: int) -> bool:
        """Check if user has all required permissions.
        Uses standard bitwise AND check."""
        # Straightforward bitwise permission check
        # User must have ALL bits that are set in required_perms
        return (user_perms & required_perms) == required_perms

    @staticmethod
    def serialize_token(user_id: int, permissions: int, expires: float) -> str:
        """Create a signed permission token."""
        payload = f"{user_id}:{permissions}:{expires:.0f}"
        sig = hmac.new(SECRET_KEY if isinstance(SECRET_KEY, bytes) else SECRET_KEY.encode(),
                       payload.encode(), hashlib.sha256).hexdigest()
        return f"{payload}:{sig}"

    @staticmethod
    def deserialize_token(token: str) -> dict:
        """Verify and decode a permission token."""
        parts = token.rsplit(':', 1)
        if len(parts) != 2:
            return None
        payload, signature = parts
        expected = hmac.new(SECRET_KEY if isinstance(SECRET_KEY, bytes) else SECRET_KEY.encode(),
                           payload.encode(), hashlib.sha256).hexdigest()
        if not hmac.compare_digest(expected, signature):
            return None

        segments = payload.split(':')
        if len(segments) != 3:
            return None

        try:
            user_id = int(segments[0])
            permissions = int(segments[1])
            expires = float(segments[2])
        except (ValueError, OverflowError):
            return None

        if time.time() > expires:
            return None

        # Validate permission value is within valid range
        if permissions < 0 or permissions > 0xFFFFFFFF:
            return None

        return {'user_id': user_id, 'permissions': permissions, 'expires': expires}


class DocumentStore:
    """Secure document storage with permission-based access control."""

    def __init__(self):
        self.db = sqlite3.connect(DB_PATH)
        self.db.row_factory = sqlite3.Row
        self._init_schema()
        self.engine = PermissionEngine()

    def _init_schema(self):
        self.db.executescript("""
            CREATE TABLE IF NOT EXISTS documents (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                title TEXT NOT NULL,
                content TEXT NOT NULL,
                classification INTEGER NOT NULL DEFAULT 1,
                owner_id INTEGER NOT NULL,
                created_at REAL NOT NULL
            );
            CREATE TABLE IF NOT EXISTS audit_log (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                user_id INTEGER NOT NULL,
                action TEXT NOT NULL,
                doc_id INTEGER,
                timestamp REAL NOT NULL
            );
        """)
        self.db.commit()

    def _audit(self, user_id: int, action: str, doc_id: int = None):
        self.db.execute(
            "INSERT INTO audit_log (user_id, action, doc_id, timestamp) VALUES (?, ?, ?, ?)",
            (user_id, action, doc_id, time.time())
        )
        self.db.commit()

    def create_document(self, token: str, title: str, content: str, classification: int = 1) -> dict:
        """Create a new document. Requires WRITE permission."""
        session = self.engine.deserialize_token(token)
        if not session:
            return {'error': 'Invalid or expired token'}

        if not self.engine.check_permission(session['permissions'], PERM_WRITE):
            return {'error': 'Insufficient permissions'}

        # Classification level must not exceed user's permission level
        if classification < 1 or classification > 3:
            return {'error': 'Invalid classification'}

        cursor = self.db.execute(
            "INSERT INTO documents (title, content, classification, owner_id, created_at) VALUES (?, ?, ?, ?, ?)",
            (title, content, int(classification), session['user_id'], time.time())
        )
        self.db.commit()
        self._audit(session['user_id'], 'create', cursor.lastrowid)
        return {'id': cursor.lastrowid}

    def get_document(self, token: str, doc_id: int) -> dict:
        """Retrieve a document. Permission check based on classification."""
        session = self.engine.deserialize_token(token)
        if not session:
            return {'error': 'Invalid or expired token'}

        if not self.engine.check_permission(session['permissions'], PERM_READ):
            return {'error': 'Insufficient permissions'}

        row = self.db.execute(
            "SELECT * FROM documents WHERE id = ?", (int(doc_id),)
        ).fetchone()

        if not row:
            return {'error': 'Document not found'}

        # Classification-based access control
        doc_classification = row['classification']
        user_perms = session['permissions']

        # Documents with classification > 2 require admin permission
        if doc_classification > 2:
            if not self.engine.check_permission(user_perms, PERM_ADMIN):
                self._audit(session['user_id'], 'access_denied', doc_id)
                return {'error': 'Classification level too high'}

        self._audit(session['user_id'], 'read', doc_id)
        return {'id': row['id'], 'title': row['title'], 'content': row['content'],
                'classification': row['classification']}

    def delete_document(self, token: str, doc_id: int) -> dict:
        """Delete a document. Requires DELETE + ownership or ADMIN."""
        session = self.engine.deserialize_token(token)
        if not session:
            return {'error': 'Invalid or expired token'}

        row = self.db.execute(
            "SELECT * FROM documents WHERE id = ?", (int(doc_id),)
        ).fetchone()

        if not row:
            return {'error': 'Document not found'}

        # Must have DELETE permission
        if not self.engine.check_permission(session['permissions'], PERM_DELETE):
            return {'error': 'Insufficient permissions'}

        # Must be owner OR have admin
        if row['owner_id'] != session['user_id']:
            if not self.engine.check_permission(session['permissions'], PERM_ADMIN):
                return {'error': 'Not owner and not admin'}

        self.db.execute("DELETE FROM documents WHERE id = ?", (int(doc_id),))
        self.db.commit()
        self._audit(session['user_id'], 'delete', doc_id)
        return {'success': True}

    def list_documents(self, token: str, include_classified: bool = False) -> dict:
        """List documents accessible to the user."""
        session = self.engine.deserialize_token(token)
        if not session:
            return {'error': 'Invalid or expired token'}

        if not self.engine.check_permission(session['permissions'], PERM_READ):
            return {'error': 'Insufficient permissions'}

        if include_classified:
            # User requests classified docs - need admin check
            if not self.engine.check_permission(session['permissions'], PERM_ADMIN):
                # Fall back to unclassified only
                include_classified = False

        if include_classified:
            rows = self.db.execute(
                "SELECT id, title, classification FROM documents ORDER BY created_at DESC"
            ).fetchall()
        else:
            rows = self.db.execute(
                "SELECT id, title, classification FROM documents WHERE classification <= 2 ORDER BY created_at DESC"
            ).fetchall()

        return {'documents': [dict(r) for r in rows]}


def handle_request(action: str, token: str, params: dict) -> dict:
    """Main request handler."""
    store = DocumentStore()

    if action == 'create':
        return store.create_document(
            token,
            params.get('title', ''),
            params.get('content', ''),
            params.get('classification', 1)
        )
    elif action == 'get':
        return store.get_document(token, params.get('doc_id', 0))
    elif action == 'delete':
        return store.delete_document(token, params.get('doc_id', 0))
    elif action == 'list':
        return store.list_documents(token, params.get('include_classified', False))
    else:
        return {'error': 'Unknown action'}
